/* @autogenerated */
import { Directive, input, TemplateRef, viewChild } from '@angular/core';
import { ExportDefinition } from '@shared/toolkit/entity-export/entity-export.model';
import { BaseAction } from './base-action';

/**
 * Acción de exportación a Excel: está en la barra general (exporta todo lo filtrado) y en la de selección
 * (pregunta si solo lo seleccionado o todo). Su plantilla `#exportTemplate` muestra
 * `<entity-export [definition]="definition" [selection]="selection()" [filter]="filter()" (closed)="close()" />`.
 *
 * Visible si el ACL genérico permite `list`.
 */
@Directive()
export abstract class BaseExportAction<T> extends BaseAction<T> {
  readonly name = 'export';
  override readonly contextual = false;
  override readonly multiple = true;
  override readonly render = viewChild<TemplateRef<any>>('exportTemplate');
  /** Filtro actual del listado: sin selección se exporta todo lo que coincide con él. */
  readonly filter = input<any>({});

  abstract readonly definition: ExportDefinition<T>;

  run(): void {
    // La pantalla pregunta qué exportar (si hay selección) y lanza la descarga
  }

  close(): void {
    this.container()?.close();
  }

  protected override get permission(): string {
    return 'list';
  }
}
